edits.before:
constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
  super(element, config)

  this._calendar = null
  this._isShown = false

  this._initCalendar()
}

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.after:
  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()

  // Set up Tab key capture listener to hide calendar without preventing default focus move
  if (this._isInput) {
    this._onTabKeyDownCapture = (event: KeyboardEvent) => {
      if (event.key === 'Tab') {
        event.stopImmediatePropagation()
        this.hide()
      }
    }
    this._element.addEventListener('keydown', this._onTabKeyDownCapture, { capture: true })
  }
}

edits.before:
override dispose(): void {
  if (this._themeObserver) {
    this._themeObserver.disconnect()
    this._themeObserver = null
  }

  if (this._onOutside) {
    EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
  }

  if (this._onTriggerClick) {
    EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
  }

  if (this._calendar) {
    this._calendar.destroy()
  }

  this._calendar = null
  super.dispose()
}

edits.after:
override dispose(): void {
  if (this._themeObserver) {
    this._themeObserver.disconnect()
    this._themeObserver = null
  }

  if (this._onOutside) {
    EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
  }

  if (this._onTriggerClick) {
    EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
  }

  // Clean up Tab key capture listener
  if (this._onTabKeyDownCapture) {
    this._element.removeEventListener('keydown', this._onTabKeyDownCapture, { capture: true })
    this._onTabKeyDownCapture = null
  }

  if (this._calendar) {
    this._calendar.destroy()
  }

  this._calendar = null
  super.dispose()
}
